# First, let's filter reviews that mention "service" (case-insensitive)
import re

service_reviews = {}
for row in dataset:
    bid = row['business_id']
    text = row['text']
    # Check if review mentions service
    if re.search(r'\bservice\b', text, re.IGNORECASE):
        if bid not in service_reviews:
            service_reviews[bid] = []
        service_reviews[bid].append(row)

print(f"Business IDs with service mentions: {len(service_reviews)}")
print("\nService review counts per business:")
service_counts = {bid: len(reviews) for bid, reviews in service_reviews.items()}
sorted_counts = sorted(service_counts.items(), key=lambda x: x[1], reverse=True)
for bid, count in sorted_counts[:20]:
    print(f"  {bid}: {count} service reviews")

# Check the target business
target_bid = "9eYm5gwEOhBQdkg9ihV7EA"
print(f"\nTarget business ({target_bid}) service reviews: {service_counts.get(target_bid, 0)}")
